// دریافت داده از نود قبلی
const response = $input.first().json;

// استخراج تفکیک بر اساس ایندکس
const byIndex = response?.aggregations?.by_index?.buckets || [];

// استخراج مجموع کلی بر اساس نوع خطا
const totalByType = response?.aggregations?.total_by_type?.buckets || {};

// پردازش هر ایندکس
const indexResults = [];
for (const bucket of byIndex) {
    const indexName = bucket.key || 'unknown';
    const totalCount = bucket.doc_count || 0;

    // استخراج تفکیک خطاها در این ایندکس
    const categories = bucket?.error_categories?.buckets || {};

    const indexData = {
        index: indexName,
        total_errors: totalCount,
        errors: {
            '5xx': categories['5xx']?.doc_count || 0,
            'connection_refused': categories['connection_refused']?.doc_count || 0,
            'database': categories['database']?.doc_count || 0,
            'timeout': categories['timeout']?.doc_count || 0
        }
    };

    // استخراج نام اپلیکیشن از ایندکس
    // مثال: operationlog-card-kms-4052-2026-08-24 -> card-kms
    const parts = indexName.split('-');
    let appName;
    if (parts.length >= 3) {
        appName = parts.slice(1, 3).join('-'); // card-kms
    } else {
        appName = indexName;
    }

    indexData.app_name = appName;
    indexResults.push(indexData);
}

// محاسبه مجموع کلی
const totalByTypeResult = {
    '5xx': totalByType['5xx']?.doc_count || 0,
    'connection_refused': totalByType['connection_refused']?.doc_count || 0,
    'database': totalByType['database']?.doc_count || 0,
    'timeout': totalByType['timeout']?.doc_count || 0
};
const totalErrors = Object.values(totalByTypeResult).reduce((sum, val) => sum + val, 0);

// تنظیم زمان ایران در JavaScript
const now = new Date();
// برای تنظیم منطقه زمانی ایران، میتونیم از toLocaleString استفاده کنیم
const options = { 
    timeZone: 'Asia/Tehran',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
};
const formattedDate = now.toLocaleString('fa-IR', options);
// تبدیل به فرمت ISO برای ذخیره
const isoDate = new Date(now.toLocaleString('en-US', { timeZone: 'Asia/Tehran' })).toISOString();

// ساخت گزارش متنی
let textReport = ` گزارش خطاهای زیرساختی - ۱۰ دقیقه اخیر
 زمان: ${formattedDate} (ایران)

 مجموع کل خطاها: ${totalErrors.toLocaleString()}

 تفکیک کلی بر اساس نوع خطا:
  • 5xx (سرور): ${totalByTypeResult['5xx'].toLocaleString()}
  • Connection Refused: ${totalByTypeResult['connection_refused'].toLocaleString()}
  • Database: ${totalByTypeResult['database'].toLocaleString()}
  • Timeout: ${totalByTypeResult['timeout'].toLocaleString()}

${'='.repeat(60)}
 تفکیک بر اساس اپلیکیشن/سرویس:
`;

// اضافه کردن اطلاعات هر ایندکس
for (const item of indexResults) {
    if (item.total_errors > 0) {
        textReport += `
${item.app_name} (${item.index})
   مجموع: ${item.total_errors.toLocaleString()}
   ├─ 5xx: ${item.errors['5xx'].toLocaleString()}
   ├─ Connection Refused: ${item.errors['connection_refused'].toLocaleString()}
   ├─ Database: ${item.errors['database'].toLocaleString()}
   └─ Timeout: ${item.errors['timeout'].toLocaleString()}
`;
    }
}

// بازگشت خروجی برای n8n
return [
    {
        json: {
            // خلاصه کلی
            summary: {
                total_errors: totalErrors,
                time_range: 'last_10_minutes',
                timestamp: isoDate,
                by_type: totalByTypeResult
            },
            // تفکیک بر اساس ایندکس
            by_index: indexResults,
            // گزارش‌های متنی برای ایمیل
            text_report: textReport,
            // داده‌های خام برای پردازش بیشتر
            raw: {
                total_hits: response?.hits?.total?.value || 0,
                took_ms: response?.took || 0
            }
        }
    }
];

// دریافت لیست ایندکس‌ها
const byIndex = $input.first().json.by_index || [];

const teamEmails = {
    'card-kms': 'team-card@company.com',
    'chakavak': 'team-chakavak@company.com',
    'core-deposit': 'team-core@company.com',
    'modern-cm': 'team-cm@company.com',
    'modern-netway': 'team-netway@company.com',
    'pol-cutoff': 'team-pol@company.com',
};

// گروه‌بندی ایمیل‌ها بر اساس تیم
const emailGroups = {};
for (const item of byIndex) {
    if (item.total_errors > 0) {
        const appName = item.app_name;
        const teamEmail = teamEmails[appName] || 'default-team@company.com';

        if (!emailGroups[teamEmail]) {
            emailGroups[teamEmail] = {
                to: teamEmail,
                services: [],
                total_errors: 0
            };
        }

        emailGroups[teamEmail].services.push({
            app_name: appName,
            index: item.index,
            errors: item.errors,
            total_errors: item.total_errors
        });
        emailGroups[teamEmail].total_errors += item.total_errors;
    }
}

// ساخت ایمیل برای هر گروه
const emailsToSend = [];
for (const [teamEmail, group] of Object.entries(emailGroups)) {
    let emailContent = ` گزارش خلاصه خطاهای تیم\n\n`;
    emailContent += `مجموع کل خطاها: ${group.total_errors.toLocaleString()}\n\n`;
    emailContent += `سرویس‌های دارای خطا:\n`;

    for (const service of group.services) {
        emailContent += `
${service.app_name} (${service.index})
   مجموع: ${service.total_errors.toLocaleString()}
   ├─ 5xx: ${service.errors['5xx'].toLocaleString()}
   ├─ Connection Refused: ${service.errors['connection_refused'].toLocaleString()}
   ├─ Database: ${service.errors['database'].toLocaleString()}
   └─ Timeout: ${service.errors['timeout'].toLocaleString()}
`;
    }

    emailsToSend.push({
        to: teamEmail,
        subject: `گزارش خلاصه خطاهای تیم شما`,
        text: emailContent,
        total_errors: group.total_errors,
        service_count: group.services.length
    });
}

return emailsToSend;
